//! Pure, synchronous OCR scheduling math for mokuro-bunko, ported from the
//! 0.5.2 Python (`ocr/job_order.py`, `eta.py`, `congestion.py`,
//! `throughput.py`, `volume_outlook.py`, the verdict half of
//! `engine_runner.py`, and the pure helpers of `watcher.py` /
//! `processor.py`). See `docs/rust-port/spec/ocr-scheduling.md` §4, 8, 12, 18–21.
//!
//! Numbers, rounding (Python's half-to-even `round`), ordering and the
//! sentences shown in the UI are reproduced exactly; `tests/golden/` holds
//! fixtures generated by the 0.5.2 code and the tests replay them.
//!
//! No I/O except the small helpers that read and write the three JSON state
//! files (`.ocr-failures.json`, `.ocr-congestion.json`, `.ocr-bench.json`)
//! in their 0.5.2 format, and [`rate::FilePriors`], which reads the latter two.

pub mod bench;
pub mod bench_file;
pub mod breaker;
pub mod congestion;
pub mod eft;
pub mod failures;
pub mod job_order;
pub mod outlook;
pub mod plan;
pub mod precision;
pub mod py;
