pub mod throughput;
mod unicode_tables;

use std::path::PathBuf;

/// Errors of the state-file helpers (the math itself does not fail).
#[derive(Debug, thiserror::Error)]
pub enum SchedError {
    #[error("could not write {path}: {source}")]
    Io {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },
}

pub use congestion::{
    average_runs, build_record, pipeline_verdict, summarize, summarize_event_stats, widen_target,
};
pub use eft::{EftDecision, EftLane, EftLeft, earliest_finish_claim};
